// ---- host logic: examples/api_tours/geometry_focus/host.cpp ----
// API tour (C++ Wrapper): layout geometry, scrolling, anchored placement, text measurement, focus
// and pointer capture. Same page, checks and case as examples/c/ports/kui_api_geometry_focus.c (and
// the Go / Rust ports): on start the host calls every method once, checks the numbers against the
// CSS on the page (and against each other) and logs one row per check into #tour-log; #tour-result
// ends as "PASS n/n (known bugs: k)". The panel buttons repeat the calls on the visible boxes.
//
// Document::dispatchMouse (kui_devtools_dispatch_mouse_event) injects the mouse input for the
// pointer-capture checks through the same dispatch path as real input.

#include <cmath>
#include <cstdlib>
#include <functional>
#include <sstream>
#include <vector>

namespace {

kui::Document* g_doc = nullptr;

// ---- Self-check bookkeeping: count, log one <tr> per check, publish the verdict ----------
// check():  a documented behaviour; a failure makes the tour FAIL.
// known():  a documented behaviour the engine currently gets wrong (reported bug). A failure is
//           logged as "KNOWN BUG" and kept out of the verdict; once it passes it counts as ok.

int g_total = 0;
int g_failed = 0;
int g_known = 0;
std::string g_failed_names;

template <typename... Parts>
std::string cat(const Parts&... parts) {
    std::ostringstream out;
    out.setf(std::ios::fixed);
    out.precision(1);
    (out << ... << parts);
    return out.str();
}

void log_row(const std::string& name, const std::string& result, const std::string& cell) {
    kui::Element* log = g_doc->getElementById("tour-log");
    if (!log) return;
    auto row = g_doc->createElement("tr");
    row->setAttribute("data-check", name);
    row->setAttribute("data-result", result);
    if (result != "ok") row->addClass("bad");
    auto first = g_doc->createElement("td");
    first->setTextContent(name);
    row->appendChild(first);
    auto second = g_doc->createElement("td");
    second->setTextContent(cell);
    row->appendChild(second);
    log->appendChild(row);
}

void check(const std::string& name, bool ok, const std::string& detail) {
    g_total++;
    if (ok) {
        log_row(name, "ok", "ok");
        return;
    }
    g_failed++;
    g_failed_names += (g_failed_names.empty() ? "" : ", ") + name;
    std::fprintf(stderr, "tour check failed: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "fail", "FAIL: " + detail);
}

void known(const std::string& name, bool ok, const std::string& bug, const std::string& detail) {
    if (ok) {
        g_total++;
        log_row(name, "ok", "ok");
        return;
    }
    g_known++;
    std::fprintf(stderr, "tour known bug: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "known", "KNOWN BUG: " + bug + " (" + detail + ")");
}

void finish() {
    kui::Element* result = g_doc->getElementById("tour-result");
    if (!result) return;
    std::string text = g_failed == 0 ? cat("PASS ", g_total, "/", g_total)
                                     : cat("FAIL ", g_failed, "/", g_total, ": ", g_failed_names);
    if (g_known) text += cat(" (known bugs: ", g_known, ")");
    result->setTextContent(text);
    result->setAttribute("data-total", std::to_string(g_total));
    result->setAttribute("data-failed", std::to_string(g_failed));
    result->setAttribute("data-known", std::to_string(g_known));
    result->addClass(g_failed == 0 ? "pass" : "fail");
}

// A Wrapper method that throws (kui::Error) fails its group instead of aborting the tour.
void run_group(const char* group, const std::function<void()>& body) {
    try {
        body();
    } catch (const std::exception& error) {
        check(cat(group, ".exception"), false, error.what());
    }
}

// ---- Small readers ------------------------------------------------------------------------

struct Box4 {
    float x = 0, y = 0, w = 0, h = 0;
};

bool near(float a, float b, float tolerance) { return std::fabs(a - b) <= tolerance; }

kui::Element* by_id(const char* id) { return g_doc->getElementById(id); }

kui::Rect rect_of(const char* id) {
    kui::Element* element = by_id(id);
    return element ? element->boundingClientRect() : kui::Rect{};
}

Box4 client_of(const char* id) {
    kui::Element* e = by_id(id);
    return e ? Box4{e->clientLeft(), e->clientTop(), e->clientWidth(), e->clientHeight()} : Box4{};
}

Box4 offset_of(const char* id) {
    kui::Element* e = by_id(id);
    return e ? Box4{e->offsetLeft(), e->offsetTop(), e->offsetWidth(), e->offsetHeight()} : Box4{};
}

Box4 scroll_of(const char* id) {
    kui::Element* e = by_id(id);
    return e ? Box4{e->scrollLeft(), e->scrollTop(), e->scrollWidth(), e->scrollHeight()} : Box4{};
}

bool box_is(const Box4& box, float x, float y, float w, float h) {
    return near(box.x, x, 0.01f) && near(box.y, y, 0.01f) && near(box.w, w, 0.01f) && near(box.h, h, 0.01f);
}

std::string box_text(const Box4& box) {
    return cat(std::lround(box.x), ",", std::lround(box.y), " ", std::lround(box.w), "x", std::lround(box.h));
}

int focused(const char* id) {
    kui::Element* element = by_id(id);
    return element ? (element->hasFocus() ? 1 : 0) : -1;
}

int captured(const char* id, int pointer_id) {
    kui::Element* element = by_id(id);
    return element ? (element->hasPointerCapture(pointer_id) ? 1 : 0) : -1;
}

void set_text(const char* id, const std::string& text) {
    if (kui::Element* element = by_id(id)) element->setTextContent(text);
}

// Injects one mouse event at the centre of an element (viewport coordinates).
void mouse_at(const char* id, KuiCMouseEventType type, KuiCMouseButton button) {
    const kui::Rect rect = rect_of(id);
    g_doc->dispatchMouse(type, rect.x + rect.width / 2, rect.y + rect.height / 2, button, 0,
                         type == KUI_C_MOUSE_MOVED ? 0 : 1);
}

// ---- Box metrics: bounding rect, client (padding box), offset (border box vs offset parent) --

void check_box_metrics() {
    const kui::Rect frame = rect_of("geo-frame");
    const kui::Rect box = rect_of("geo-box");
    const kui::Rect bb = rect_of("geo-bb");
    const Box4 client_box = client_of("geo-box");
    const Box4 client_bb = client_of("geo-bb");
    const Box4 offset_box = offset_of("geo-box");
    const Box4 offset_bb = offset_of("geo-bb");

    // content-box: 200 + 2*12 padding + 2*6 border; border-box: the declared 200x50.
    check("geo.bounding_rect-size",
          near(box.width, 236, 0.5f) && near(box.height, 76, 0.5f) && near(bb.width, 200, 0.5f) &&
          near(bb.height, 50, 0.5f),
          cat("content-box ", box.width, "x", box.height, " (want 236x76), border-box ", bb.width, "x",
              bb.height, " (want 200x50)"));
    // Frame border 2 + frame padding 8 + box margin 10 from the frame's edge.
    check("geo.bounding_rect-position", near(box.x - frame.x, 20, 0.5f) && near(box.y - frame.y, 20, 0.5f),
          cat("box at +", box.x - frame.x, ",+", box.y - frame.y, " from the frame (want +20,+20)"));
    // Padding box: left/top are the border widths.
    check("geo.client_metrics", box_is(client_box, 6, 6, 224, 64) && box_is(client_bb, 4, 4, 192, 42),
          cat("content-box ", box_text(client_box), " (want 6,6 224x64), border-box ", box_text(client_bb),
              " (want 4,4 192x42)"));
    // Border box from the offset parent's padding edge; the boxes' 10px margins collapse.
    check("geo.offset_metrics", box_is(offset_box, 18, 18, 236, 76) && box_is(offset_bb, 18, 104, 200, 50),
          cat("content-box ", box_text(offset_box), " (want 18,18 236x76), border-box ", box_text(offset_bb),
              " (want 18,104 200x50)"));
    // offsetLeft/Top = the bounding rects' distance minus the parent's border, rounded.
    check("geo.offset_vs_rect",
          offset_bb.x == std::floor(bb.x - frame.x - 2 + 0.5f) &&
          offset_bb.y == std::floor(bb.y - frame.y - 2 + 0.5f) &&
          offset_bb.w == std::floor(bb.width + 0.5f) && offset_bb.h == std::floor(bb.height + 0.5f),
          cat("offset ", offset_bb.x, ",", offset_bb.y, " vs rects ", bb.x - frame.x - 2, ",",
              bb.y - frame.y - 2));
}

// ---- Scrolling: extent, scrollTo, scrollBy, clamping ----------------------------------------

void scroll_to(float left, float top) {
    if (kui::Element* scroller = by_id("scroller")) scroller->scrollTo(left, top);
}

void scroll_by(float dx, float dy) {
    if (kui::Element* scroller = by_id("scroller")) scroller->scrollBy(dx, dy);
}

void check_scrolling() {
    const kui::Rect outer = rect_of("scroller");
    const kui::Rect row0 = rect_of("row-0");
    const Box4 client = client_of("scroller");
    Box4 scroll = scroll_of("scroller");

    check("scroll.extent", box_is(scroll, 0, 0, 600, 400), cat("scroll ", box_text(scroll), " (want 0,0 600x400)"));
    // 1px border; a rendered scrollbar may take some of the padding box.
    check("scroll.client", client.x == 1 && client.y == 1 && client.w <= outer.width - 2 &&
          client.w > outer.width - 24 && client.h <= 118 && client.h > 96,
          cat("client ", box_text(client), " of a ", outer.width, "x", outer.height, " box"));

    scroll_to(0, 100);
    scroll = scroll_of("scroller");
    kui::Rect moved = rect_of("row-0");
    check("scroll.set_scroll_position", near(scroll.y, 100, 0.01f) && near(scroll.x, 0, 0.01f) &&
          near(row0.y - moved.y, 100, 0.5f),
          cat("scroll ", scroll.x, ",", scroll.y, ", row 0 moved up ", row0.y - moved.y));

    scroll_by(30, 50);
    scroll = scroll_of("scroller");
    moved = rect_of("row-0");
    check("scroll.scroll_by", near(scroll.x, 30, 0.01f) && near(scroll.y, 150, 0.01f) &&
          near(row0.x - moved.x, 30, 0.5f) && near(row0.y - moved.y, 150, 0.5f),
          cat("scroll ", scroll.x, ",", scroll.y, ", row 0 moved ", row0.x - moved.x, ",", row0.y - moved.y));

    // Past the end clamps to extent - client size.
    scroll_to(10000, 10000);
    scroll = scroll_of("scroller");
    check("scroll.clamp", near(scroll.x, 600 - client.w, 0.5f) && near(scroll.y, 400 - client.h, 0.5f),
          cat("scroll ", scroll.x, ",", scroll.y, " (want ", 600 - client.w, ",", 400 - client.h, ")"));

    scroll_to(0, 0);
    scroll = scroll_of("scroller");
    moved = rect_of("row-0");
    check("scroll.reset", near(scroll.x, 0, 0.01f) && near(scroll.y, 0, 0.01f) && near(moved.y, row0.y, 0.5f),
          cat("scroll ", scroll.x, ",", scroll.y));
}

// ---- Scroll into view and inertial scrolling ----------------------------------------------------

void check_scroll_reveal() {
    kui::Element* scroller = by_id("scroller");
    kui::Element* last = by_id("row-9");
    if (!scroller || !last) {
        check("reveal.setup", false, "missing #scroller or #row-9");
        return;
    }
    scroll_to(0, 0);
    last->scrollIntoView(true);
    const Box4 scroll = scroll_of("scroller");
    const kui::Rect box = rect_of("scroller");
    const kui::Rect row = rect_of("row-9");
    // The last row is now inside the scroll box (1px border).
    check("scroll.scroll_into_view", scroll.y > 100 && row.y >= box.y && row.y + row.height <= box.y + box.height + 1,
          cat("scroll ", scroll.x, ",", scroll.y, ", row 9 at ", row.y, "+", row.height, " in a box at ", box.y, "+", box.height));

    // Inertial scroll: a velocity (px/ms) that decays frame by frame until the container stops.
    scroll_to(0, 0);
    std::string error;
    try {
        scroller->startMomentumScroll(0.0f, 0.1f);
    } catch (const kui::Error& thrown) {
        error = thrown.what();
    }
    float previous = -1.0f, now_y = 0.0f;
    for (int i = 0; i < 80; ++i) {
        kui::Platform::waitEvents(0.03);
        now_y = scroll_of("scroller").y;
        if (now_y > 0 && now_y == previous) break;
        previous = now_y;
    }
    check("scroll.start_momentum_scroll", error.empty() && now_y > 0 && now_y < 200,
          cat("error '", error, "', stopped at ", now_y));
    scroll_to(0, 0);
}

// ---- Anchored placement: positionRelativeTo with placements, flip and clamp ----------------

void place(const char* placement, float offset, bool flip, bool clamp, float margin) {
    kui::Element* popup = by_id("pos-popup");
    kui::Element* anchor = by_id("pos-anchor");
    kui::Element::PositioningOptions options;
    options.flip = flip;
    options.clampToViewport = clamp;
    options.offset = offset;
    options.viewportMargin = margin;
    if (popup && anchor) popup->positionRelativeTo(anchor, placement, options);
}

void check_placement() {
    const kui::Rect a = rect_of("pos-anchor");

    place("bottom-start", 6, false, false, 0);
    kui::Rect p = rect_of("pos-popup");
    check("pos.bottom-start", near(p.x, a.x, 0.5f) && near(p.y, a.y + a.height + 6, 0.5f),
          cat("popup ", p.x, ",", p.y, " anchor ", a.x, ",", a.y, " ", a.width, "x", a.height));
    {
        kui::Element* popup = by_id("pos-popup");
        const std::string left = popup ? popup->style()->getPropertyValue("left") : std::string();
        const bool px = left.size() > 2 && left.compare(left.size() - 2, 2, "px") == 0;
        check("pos.inline-left", px && near(static_cast<float>(std::atof(left.c_str())), a.x, 0.5f),
              cat("inline left '", left, "'"));
    }

    place("right-center", 4, false, false, 0);
    p = rect_of("pos-popup");
    check("pos.right-center", near(p.x, a.x + a.width + 4, 0.5f) &&
          near(p.y + p.height / 2, a.y + a.height / 2, 0.5f),
          cat("popup ", p.x, ",", p.y, " ", p.width, "x", p.height));

    place("left-end", 8, false, false, 0);
    p = rect_of("pos-popup");
    check("pos.left-end", near(p.x + p.width, a.x - 8, 0.5f) && near(p.y + p.height, a.y + a.height, 0.5f),
          cat("popup ", p.x, ",", p.y, " ", p.width, "x", p.height));

    // "top" with a viewport margin below the anchor's top cannot fit: flip puts it below.
    place("top", 5, true, false, a.y);
    p = rect_of("pos-popup");
    check("pos.flip", near(p.y, a.y + a.height + 5, 0.5f), cat("popup y ", p.y, " (want ", a.y + a.height + 5, ")"));

    // Far to the left with clamping: held at the viewport margin.
    place("left", 2000, false, true, 7);
    p = rect_of("pos-popup");
    check("pos.clamp", near(p.x, 7, 0.5f), cat("popup x ", p.x, " (want 7)"));

    // Back to the default placement (default PositioningOptions: flip + clamp, margin 8 -> use 4).
    place("bottom-start", 6, true, true, 4);
}

// ---- Text measurement -----------------------------------------------------------------------

kui::TextMetrics measure(const char* text, const char* family, float size, int weight) {
    kui::Element* sample = by_id("measure-sample");
    kui::TextStyle style;  // fontFamily defaults to "sans-serif", the C ABI's NULL
    if (family) style.fontFamily = family;
    style.fontSize = size;
    style.fontWeight = static_cast<kui::u16>(weight);
    return sample ? sample->measureText(text, style) : kui::TextMetrics{};
}

void check_measure() {
    const kui::TextMetrics small = measure("Hello KUI", nullptr, 12, 400);
    const kui::TextMetrics mid = measure("Hello KUI", nullptr, 16, 400);
    const kui::TextMetrics large = measure("Hello KUI", nullptr, 24, 400);
    const kui::TextMetrics empty = measure("", nullptr, 16, 400);
    const kui::TextMetrics segoe = measure("Hello KUI", "Segoe UI", 16, 400);
    const kui::Rect span = rect_of("measure-span");

    check("measure.monotonic", small.width > 0 && small.width < mid.width && mid.width < large.width,
          cat("widths ", small.width, " / ", mid.width, " / ", large.width, " at 12 / 16 / 24px"));
    check("measure.metrics", mid.ascent > 0 && mid.descent > 0 &&
          mid.lineHeight >= mid.ascent + mid.descent - 0.5f && large.ascent > mid.ascent,
          cat("ascent ", mid.ascent, " descent ", mid.descent, " line height ", mid.lineHeight));
    check("measure.empty", empty.width == 0 && near(empty.ascent, mid.ascent, 0.01f),
          cat("empty width ", empty.width, " ascent ", empty.ascent));
    // Same shaping as layout: the inline-block span with the same text, font and size.
    check("measure.matches_layout", near(segoe.width, span.width, 1.0f),
          cat("measured ", segoe.width, ", laid-out span ", span.width));
}

// ---- Focus: focus / blur / hasFocus, and the focus / blur events they fire ------------------

int g_focus_events = 0;
int g_blur_events = 0;

void focus_id(const char* id) {
    if (kui::Element* element = by_id(id)) element->focus();
}

void blur_id(const char* id) {
    if (kui::Element* element = by_id(id)) element->blur();
}

void check_focus() {
    if (kui::Element* div = by_id("f-div")) div->addEventListener("focus", [] { g_focus_events++; });
    if (kui::Element* input = by_id("f-input")) input->addEventListener("blur", [] { g_blur_events++; });

    focus_id("f-btn");
    check("focus.button", focused("f-btn") == 1, cat("has_focus(button) = ", focused("f-btn")));

    focus_id("f-input");
    check("focus.moves", focused("f-input") == 1 && focused("f-btn") == 0,
          cat("input ", focused("f-input"), ", button ", focused("f-btn")));

    blur_id("f-input");
    check("focus.blur", focused("f-input") == 0 && g_blur_events == 1,
          cat("has_focus(input) = ", focused("f-input"), ", blur events ", g_blur_events));

    focus_id("f-div");
    check("focus.tabindex", focused("f-div") == 1 && g_focus_events == 1,
          cat("has_focus(div) = ", focused("f-div"), ", focus events ", g_focus_events));

    // A div without tabindex is not focusable (HTML focus()): focus() changes nothing.
    focus_id("f-plain");
    known("focus.not_focusable", focused("f-plain") == 0 && focused("f-div") == 1,
          "focus() also focuses an element that is not focusable (div without tabindex)",
          cat("plain ", focused("f-plain"), ", tabindex div ", focused("f-div")));

    blur_id("f-div");
}

// ---- Pointer capture: set / has / release, the capture events, routing, implicit release ---

int g_got_capture = 0;
int g_lost_capture = 0;
int g_captured_moves = 0;
bool g_capture_target = false;  // true when gotpointercapture's current target was #cap-box

void capture(bool on) {
    kui::Element* box = by_id("cap-box");
    if (box && on) box->setPointerCapture(1);
    if (box && !on) box->releasePointerCapture(1);
}

void check_capture() {
    if (kui::Element* box = by_id("cap-box")) {
        box->addEventListener("gotpointercapture", [](kui::Event& event) {
            g_got_capture++;
            kui::Element* current = event.currentTarget();
            g_capture_target = current && current->id() == "cap-box";
            if (kui::Element* target = by_id("cap-box")) target->setClassName("captured");
        });
        box->addEventListener("lostpointercapture", [] {
            g_lost_capture++;
            if (kui::Element* target = by_id("cap-box")) target->setClassName("");
        });
        box->addEventListener("pointermove", [] { g_captured_moves++; });
    }

    check("cap.initial", captured("cap-box", 1) == 0, cat("has_pointer_capture(1) = ", captured("cap-box", 1)));

    capture(true);
    check("cap.set", captured("cap-box", 1) == 1 && captured("cap-box", 2) == 0 && g_got_capture == 1,
          cat("pointer 1 ", captured("cap-box", 1), ", pointer 2 ", captured("cap-box", 2),
              ", gotpointercapture ", g_got_capture));
    // The capture events are dispatched at the capturing element.
    known("cap.event_target", g_capture_target,
          "gotpointercapture / lostpointercapture have no target or current target",
          cat("current target is #cap-box: ", g_capture_target ? 1 : 0));

    // A move over another element is delivered to the capturing box.
    const int moves = g_captured_moves;
    mouse_at("cap-other", KUI_C_MOUSE_MOVED, KUI_C_MOUSE_BUTTON_NONE);
    check("cap.routes_moves", g_captured_moves == moves + 1,
          cat("pointermove on the box ", moves, " -> ", g_captured_moves));

    capture(false);
    check("cap.release", captured("cap-box", 1) == 0 && g_lost_capture == 1,
          cat("has_pointer_capture(1) = ", captured("cap-box", 1), ", lostpointercapture ", g_lost_capture));

    // Releasing the button ends a capture by itself (implicit release).
    capture(true);
    mouse_at("cap-other", KUI_C_MOUSE_PRESSED, KUI_C_MOUSE_BUTTON_LEFT);
    mouse_at("cap-other", KUI_C_MOUSE_RELEASED, KUI_C_MOUSE_BUTTON_LEFT);
    check("cap.implicit_release", captured("cap-box", 1) == 0 && g_lost_capture == 2,
          cat("has_pointer_capture(1) = ", captured("cap-box", 1), ", lostpointercapture ", g_lost_capture));
    mouse_at("cap-other", KUI_C_MOUSE_MOVED, KUI_C_MOUSE_BUTTON_NONE);
}

// ---- Panel buttons -----------------------------------------------------------------------

bool g_wide_padding = false;

void show_geo() {
    const Box4 client = client_of("geo-box");
    const Box4 offset = offset_of("geo-box");
    const kui::Rect rect = rect_of("geo-box");
    set_text("geo-out", cat("rect ", std::lround(rect.width), "x", std::lround(rect.height), " | client ",
                            box_text(client), " | offset ", std::lround(offset.x), ",", std::lround(offset.y)));
}

void on_geo_pad() {
    g_wide_padding = !g_wide_padding;
    if (kui::Element* box = by_id("geo-box")) box->style()->setProperty("padding", g_wide_padding ? "20px" : "12px");
    show_geo();
}

void show_scroll() {
    const Box4 scroll = scroll_of("scroller");
    set_text("scroll-out", cat("left=", std::lround(scroll.x), " top=", std::lround(scroll.y)));
}

void show_pos(const char* placement) {
    const kui::Rect a = rect_of("pos-anchor");
    const kui::Rect p = rect_of("pos-popup");
    set_text("pos-out", cat(placement, ": dx=", std::lround(p.x - a.x), " dy=", std::lround(p.y - a.y)));
}

int g_measure_size = 16;
bool g_measure_bold = false;

void show_measure() {
    const kui::TextMetrics metrics = measure("Hello KUI", "Segoe UI", static_cast<float>(g_measure_size),
                                             g_measure_bold ? 700 : 400);
    if (kui::Element* sample = by_id("measure-sample")) {
        sample->style()->setProperty("font-size", cat(g_measure_size, "px"));
        sample->style()->setProperty("font-weight", g_measure_bold ? "700" : "400");
    }
    set_text("measure-out", cat("size=", g_measure_size, g_measure_bold ? " bold" : "", " width=", metrics.width,
                                " ascent=", metrics.ascent, " descent=", metrics.descent, " line=",
                                metrics.lineHeight));
}

void show_focus(const std::string& note) {
    set_text("focus-out", cat(note, " | button=", focused("f-btn"), " input=", focused("f-input"), " div=",
                              focused("f-div"), " plain=", focused("f-plain")));
}

void on_focus_blur() {
    focus_id("f-input");
    const int before = focused("f-input");
    blur_id("f-input");
    show_focus(cat("focus+blur(input) ", before, "->", focused("f-input")));
}

void show_capture() {
    set_text("cap-out", cat("captured=", captured("cap-box", 1) == 1 ? "yes" : "no", " | got=", g_got_capture,
                            " lost=", g_lost_capture, " moves=", g_captured_moves));
}

// Clicks on #id run `handler` (a missing button is reported as a failed check).
void on_click(const char* id, void (*handler)()) {
    kui::Element* button = by_id(id);
    if (!button) {
        check(cat("ui.", id), false, "button missing");
        return;
    }
    button->addEventListener("click", [handler](kui::Event&) { handler(); });
}

}  // namespace

void tour_ready(kui::Window& window, kui::Document& document) {
    (void)window;
    g_doc = &document;

    run_group("geo", check_box_metrics);
    run_group("scroll", check_scrolling);
    run_group("reveal", check_scroll_reveal);
    run_group("pos", check_placement);
    run_group("measure", check_measure);
    run_group("focus", check_focus);
    run_group("cap", check_capture);
    finish();

    on_click("btn-geo-show", show_geo);
    on_click("btn-geo-pad", on_geo_pad);
    on_click("btn-scroll-down", [] { scroll_by(0, 40); show_scroll(); });
    on_click("btn-scroll-right", [] { scroll_by(50, 0); show_scroll(); });
    on_click("btn-scroll-end", [] { scroll_to(10000, 10000); show_scroll(); });
    on_click("btn-scroll-top", [] { scroll_to(0, 0); show_scroll(); });
    on_click("btn-pos-below", [] { place("bottom-start", 6, true, true, 4); show_pos("bottom-start"); });
    on_click("btn-pos-right", [] { place("right-center", 6, true, true, 4); show_pos("right-center"); });
    on_click("btn-pos-left", [] { place("left-end", 6, true, true, 4); show_pos("left-end"); });
    on_click("btn-measure-smaller", [] { if (g_measure_size > 8) g_measure_size -= 4; show_measure(); });
    on_click("btn-measure-larger", [] { if (g_measure_size < 40) g_measure_size += 4; show_measure(); });
    on_click("btn-measure-bold", [] { g_measure_bold = !g_measure_bold; show_measure(); });
    on_click("btn-focus-input", [] { focus_id("f-input"); show_focus("focus(input)"); });
    on_click("btn-focus-div", [] { focus_id("f-div"); show_focus("focus(div)"); });
    on_click("btn-focus-plain", [] { focus_id("f-plain"); show_focus("focus(plain)"); });
    on_click("btn-focus-blur", on_focus_blur);
    on_click("btn-cap-set", [] { capture(true); show_capture(); });
    on_click("btn-cap-release", [] { capture(false); show_capture(); });
    on_click("btn-cap-state", show_capture);
    show_measure();
}
// ---- end of examples/api_tours/geometry_focus/host.cpp ----

int main() {
    try {
        if (!kui::Platform::init()) return 3;
        kui::WindowConfig config;
        config.title = "KUI API \xe2\x80\x94 geometry, scroll & focus";
        config.width = 1100;
        config.height = 780;
        auto window = kui::Window::create(config);
        if (!window) return 4;
        kui::Document* document = window->document();
        auto script = kui::ScriptEngine::create();
        if (script) {
            script->setErrorHandler([](const std::string& error, const std::string& source, int line) {
                std::fprintf(stderr, "[Lua] %s:%d: %s\n", source.c_str(), line, error.c_str());
            });
            script->bindDocument(document);
            window->setScriptEngine(script.get());
        }
        tour_script = script.get();
        document->loadHTML(k_tour_page);
        if (script) script->executeScripts();
        // Test hook shared with the C / Go / Rust runners: KUI_EXAMPLE_DEVTOOLS_PORT=<port> starts
        // DevTools so scripts/verify_example_ports.py can click and read the DOM.
        const std::string port = tour_env("KUI_EXAMPLE_DEVTOOLS_PORT");
        if (!port.empty()) window->startDevTools(static_cast<kui::u16>(std::atoi(port.c_str())));
        tour_ready(*window, *document);
        const int code = kui::Platform::run();
        tour_script = nullptr;
        return code;
    } catch (const std::exception& error) {
        std::fprintf(stderr, "[kui_api_geometry_focus] %s\n", error.what());
        return 9;
    }
}
